<!DOCTYPE html><html><head><?php include('links.php'); ?><link rel="stylesheet" href="css/academic-plan.css"><link rel="stylesheet" href="css/academic-plan-table.css"></head><body class="academic-plan-page"><div class="header"><?php include('menu.php'); ?></div><main class="academic-plan-shell"><section class="academic-plan-hero"><div><span>SEMESTER ROADMAP</span><h1>Academic Calendar</h1><p>The official shared school itinerary. Check each week, activity, and date as you plan ahead.</p></div><div class="academic-plan-hero-card"><i class="fa fa-calendar-check-o"></i><strong><?php echo count($rows); ?> published activities</strong><small>Your semester guide.</small></div></section><section class="academic-plan-board"><div class="academic-plan-board-head"><div><span>Official school calendar</span><h2>Semester activities by week</h2></div><?php if(($_SESSION['ACCESSLEVEL']??'')==='administrator'){ ?><a href="academic-plan.php">Manage Academic Plan</a><?php } ?></div><?php if(count($rows)>0){ ?><div class="academic-plan-table-wrap"><table class="academic-plan-table"><thead><tr><th>Week</th><th>Start Date</th><th>End Date</th><th>Activity</th><th>Activity Type</th><th>Semester</th><th>Venue / Responsible Office</th></tr></thead><tbody><?php foreach($rows as $row){ ?><tr><td class="academic-plan-week-cell"><?php echo (int)$row['weeknumber']>0?'Week '.(int)$row['weeknumber']:'—'; ?></td><td><strong><?php echo date('d M Y',strtotime($row['startdate'])); ?></strong></td><td><?php echo trim((string)$row['enddate'])!==''?academic_plan_escape(date('d M Y',strtotime($row['enddate']))):'One day'; ?></td><td><strong><?php echo academic_plan_escape($row['title']); ?></strong><?php if(trim((string)$row['description'])!==''){ ?><small><?php echo academic_plan_escape($row['description']); ?></small><?php } ?></td><td><span class="academic-plan-type"><?php echo academic_plan_escape($row['eventtype']); ?></span></td><td><?php echo trim((string)$row['termname'])!==''?'Semester '.academic_plan_escape($row['termname']):'All semesters'; ?></td><td><?php echo academic_plan_escape(trim((string)$row['venue'])!==''?$row['venue']:'To be confirmed'); ?><?php if(trim((string)$row['activityowner'])!==''){ ?><small><?php echo academic_plan_escape($row['activityowner']); ?></small><?php } ?></td></tr><?php } ?></tbody></table></div><?php }else{ ?><div class="academic-plan-empty"><i class="fa fa-calendar-o"></i><strong>The academic calendar has not been published for your semester yet.</strong><p>Please check again soon.</p></div><?php } ?></section></main></body></html>
